import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import { motion, AnimatePresence } from "framer-motion";
import images from "../images";

type ProductIntro = {
  subtitle?: string;
  item?: string;
};

type IconCertificate = {
  image?: string;
};

const ProductDisplay = () => {
  const { t } = useTranslation();
  const categories = (t("products.items", { returnObjects: true }) as Array<any>) || [];
  const [openCategory, setOpenCategory] = useState<string | null>(null);

  const toggleCategory = (categoryName: string) => {
    setOpenCategory((prev) => (prev === categoryName ? null : categoryName));
  };

  return (
    <section className="text-DeepSea">
      {categories.map((category) => {
        const isOpen = openCategory === category.category;

        return (
          <div key={category.category} className="mb-6 border-b border-DeepSea pb-6">
            {/* Acordeón header con caret */}
            <button
              onClick={() => toggleCategory(category.category)}
              className="w-full flex justify-between items-center text-left text-2xl font-semibold py-4 transition-colors hover:text-Pacific"
            >
              <span>{category.category.toUpperCase()}</span>
              <motion.span
                initial={false}
                animate={{ rotate: isOpen ? 180 : 0 }}
                transition={{ duration: 0.3 }}
              >
                <img src="../up.svg" alt="Close menu" />
              </motion.span>
            </button>

            {/* Panel */}
            <AnimatePresence initial={false}>
              {isOpen && (
                <motion.div
                  key="content"
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  transition={{ duration: 0.4, ease: "easeInOut" }}
                  className="overflow-hidden"
                >
                  <div className="space-y-12 pt-6">
                    {category.products.map((product: any) => (
                      <div
                        key={product.id}
                        className="flex flex-col sm:flex-row w-full mx-auto border-t border-DeepSea pt-12"
                      >
                        <div className="w-full sm:w-1/2">
                          <img
                            src={`/${product.iconDivision}.svg`}
                            className="h-[30px] sm:h-[42px]"
                            alt={product.iconDivision}
                          />
                          <h2
                            className="head-3 sm:head-2 text-DeepSea py-6"
                            dangerouslySetInnerHTML={{ __html: product.name }}
                          />
                          <div className="body-3 sm:body-1">
                            {product.intro.map((intro: ProductIntro, idx: number) =>
                              intro.item ? (
                                <div key={idx}>
                                  {intro.subtitle && <strong>{intro.subtitle}</strong>}
                                  <p dangerouslySetInnerHTML={{ __html: intro.item }} />
                                </div>
                              ) : null
                            )}
                          </div>

                          {product.iconCertificate && (
                            <div className="flex space-x-4 mt-6 sm:mt-0 mb-6">
                              {product.iconCertificate.map(
                                (cert: IconCertificate, idx: number) => {
                                  if (!cert.image) return null;
                                  const imageData = images[cert.image];
                                  return imageData ? (
                                    <img
                                      key={idx}
                                      src={imageData.src}
                                      alt={imageData.alt || `Certificate ${idx + 1}`}
                                      className="w-12 h-12 object-contain"
                                    />
                                  ) : null;
                                }
                              )}
                            </div>
                          )}
                        </div>

                        <aside className="w-full sm:w-1/2 pl-0 sm:pl-48 space-y-6 body-3 sm:body-2 pt-4">
                          {product.aside.intro.map((text: ProductIntro, idx: number) =>
                            text.item ? <p key={idx}>{text.item}</p> : null
                          )}

                          {product.aside.applications.length > 1 && (
                            <div className="pt-6">
                              <h3 className="head-6 sm:head-5 text-DeepSea">Applications</h3>
                              <ul className={styles.lists}>
                                {product.aside.applications.map(
                                  (app: ProductIntro, idx: number) =>
                                    app.item ? (
                                      <li
                                        className={styles.listItems}
                                        key={idx}
                                        dangerouslySetInnerHTML={{ __html: app.item }}
                                      />
                                    ) : null
                                )}
                              </ul>
                            </div>
                          )}

                          {product.aside.keyFeatures.length > 1 && (
                            <div className="pt-6">
                              <h3 className="head-6 sm:head-5 text-DeepSea">Key Features</h3>
                              <ul className={styles.lists}>
                                {product.aside.keyFeatures.map(
                                  (feature: ProductIntro, idx: number) =>
                                    feature.item ? (
                                      <li
                                        className={styles.listItems}
                                        key={idx}
                                        dangerouslySetInnerHTML={{ __html: feature.item }}
                                      />
                                    ) : null
                                )}
                              </ul>
                            </div>
                          )}

                          {product.aside.keyBenefits.length > 1 && (
                            <div className="pt-6">
                              <h3 className="head-6 sm:head-5 text-DeepSea">Key Benefits</h3>
                              <ul className={styles.lists}>
                                {product.aside.keyBenefits.map(
                                  (benefit: ProductIntro, idx: number) =>
                                    benefit.item ? (
                                      <li
                                        className={styles.listItems}
                                        key={idx}
                                        dangerouslySetInnerHTML={{ __html: benefit.item }}
                                      />
                                    ) : null
                                )}
                              </ul>
                            </div>
                          )}
                        </aside>
                      </div>
                    ))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        );
      })}
    </section>
  );
};

export default ProductDisplay;

const styles = {
  lists: "list-disc mt-4 sm:mt-6",
  listItems: "my-2 ml-8 pl-2",
};